import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import styles from './ForEveryYou.module.css';

const OCCASIONS = [
  {
    id: 'date-night',
    title: 'Date Night',
    subtitle: 'Curated pieces for modern elegance',
    image: 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=1500&q=80&auto=format&fit=crop',
    description: 'Statement pieces designed to elevate intimate evenings and special moments.',
  },
  {
    id: 'office-wear',
    title: 'Office Wear',
    subtitle: 'Curated pieces for modern elegance',
    image: 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?w=1500&q=80&auto=format&fit=crop',
    description: 'Refined, wearable jewellery crafted for polished everyday confidence.',
  },
  {
    id: 'party-wear',
    title: 'Party Wear',
    subtitle: 'Curated pieces for modern elegance',
    image: 'https://images.unsplash.com/photo-1533236891686-9ce5d1a14c7f?w=1500&q=80&auto=format&fit=crop',
    description: 'Statement pieces designed to elevate every celebration.',
  },
  {
    id: 'wedding-wear',
    title: 'Wedding Wear',
    subtitle: 'Curated pieces for modern elegance',
    image: 'https://images.unsplash.com/photo-1520975919993-4f5f9d2f8a7a?w=1500&q=80&auto=format&fit=crop',
    description: 'Timeless designs perfect for vows, ceremonies and heirloom moments.',
  },
  {
    id: 'daily-wear',
    title: 'Daily Wear',
    subtitle: 'Curated pieces for modern elegance',
    image: 'https://images.unsplash.com/photo-1531297484001-80022131f5a1?w=1500&q=80&auto=format&fit=crop',
    description: 'Minimal, elegant pieces that become part of the everyday ritual.',
  },
  {
    id: 'minimal-style',
    title: 'Minimal Style',
    subtitle: 'Curated pieces for modern elegance',
    image: 'https://images.unsplash.com/photo-1519741491654-1fba7f0f5c29?w=1500&q=80&auto=format&fit=crop',
    description: 'Understated silhouettes with exceptional finish and presence.',
  },
  {
    id: 'vacation-style',
    title: 'Vacation Style',
    subtitle: 'Curated pieces for modern elegance',
    image: 'https://images.unsplash.com/photo-1503341455253-b2e723bb3dbb?w=1500&q=80&auto=format&fit=crop',
    description: 'Lightweight luxury designed for sunlit escapes and evenings abroad.',
  },
  {
    id: 'festive-glam',
    title: 'Festive Glam',
    subtitle: 'Curated pieces for modern elegance',
    image: 'https://images.unsplash.com/photo-1503342452485-86a6a41f19f9?w=1500&q=80&auto=format&fit=crop',
    description: 'Opulent accents for the most celebratory moments and gatherings.',
  },
  {
    id: 'luxury-evening',
    title: 'Luxury Evening',
    subtitle: 'Curated pieces for modern elegance',
    image: 'https://images.unsplash.com/photo-1518544880285-4b9f72a9b0a9?w=1500&q=80&auto=format&fit=crop',
    description: 'Red carpet-ready designs with cinematic presence and polish.',
  },
  {
    id: 'bridal-elegance',
    title: 'Bridal Elegance',
    subtitle: 'Curated pieces for modern elegance',
    image: 'https://images.unsplash.com/photo-1520975919993-4f5f9d2f8a7a?w=1500&q=80&auto=format&fit=crop',
    description: 'Heirloom-calibre pieces designed for life’s most treasured ceremonies.',
  },
];

const TRANSITION = '800ms';
const EASING = 'cubic-bezier(.2,.9,.25,1)';

const ForEveryYou = () => {
  const [activeIndex, setActiveIndex] = useState(2); // start slightly left for a cinematic entrance
  const touchStartX = useRef(null);
  const touchDelta = useRef(0);
  const containerRef = useRef(null);
  const navigate = useNavigate();

  // Keyboard navigation
  useEffect(() => {
    const onKey = (e) => {
      if (e.key === 'ArrowRight') {
        setActiveIndex((prev) => Math.min(prev + 1, OCCASIONS.length - 1));
      } else if (e.key === 'ArrowLeft') {
        setActiveIndex((prev) => Math.max(prev - 1, 0));
      } else if (e.key === 'Enter') {
        // Enter on active -> navigate to collections (example)
        const active = OCCASIONS[activeIndex];
        if (active) navigate(`/collections`);
      }
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [activeIndex, navigate]);

  const goTo = useCallback((index) => {
    if (index < 0) index = 0;
    if (index > OCCASIONS.length - 1) index = OCCASIONS.length - 1;
    setActiveIndex(index);
  }, []);

  const handlePrev = () => goTo(activeIndex - 1);
  const handleNext = () => goTo(activeIndex + 1);

  const handleTouchStart = (e) => {
    touchStartX.current = e.touches[0].clientX;
    touchDelta.current = 0;
  };

  const handleTouchMove = (e) => {
    if (!touchStartX.current) return;
    const x = e.touches[0].clientX;
    touchDelta.current = x - touchStartX.current;
  };

  const handleTouchEnd = () => {
    const diff = touchDelta.current;
    if (Math.abs(diff) > 40) {
      if (diff < 0) handleNext();
      else handlePrev();
    }
    touchStartX.current = null;
    touchDelta.current = 0;
  };

  const handleCardClick = (index) => {
    if (index === activeIndex) {
      // active card: navigate to collections (example route)
      navigate(`/collections`);
    } else {
      goTo(index);
    }
  };

  // Render three visible: prev, active, next, but show far prev/next for depth
  const renderCards = () => {
    return OCCASIONS.map((item, index) => {
      const offset = index - activeIndex;
      const abs = Math.abs(offset);
      let state = 'hidden';
      if (offset === 0) state = 'active';
      else if (offset === -1) state = 'left';
      else if (offset === 1) state = 'right';
      else if (offset === -2) state = 'far-left';
      else if (offset === 2) state = 'far-right';

      // For infinite feel allow neighboring wrap
      if (index === 0 && activeIndex === OCCASIONS.length - 1) {
        // first when last is active -> treat as right neighbor
      }

      return (
        <button
          key={item.id}
          className={`${styles.card} ${styles[`card-${state}`] || ''}`}
          onClick={() => handleCardClick(index)}
          aria-label={item.title}
          tabIndex={0}
        >
          <div className={styles.imageWrapper}>
            <img src={item.image} alt={item.title} className={styles.image} />
            <div className={styles.overlay} />
            <div className={styles.overlayText}>
              <div className={styles.overlayTitle}>{item.title}</div>
              <div className={styles.overlaySubtitle}>{item.subtitle}</div>
            </div>
          </div>
        </button>
      );
    });
  };

  const active = OCCASIONS[activeIndex];

  return (
    <section className={styles.section}>
      <div className={styles.container}>
        <h2 className={styles.sectionTitle}>FOR EVERY YOU</h2>
        <p className={styles.sectionSubtitle}>Jewellery curated for every mood, moment and occasion.</p>

        <div
          ref={containerRef}
          className={styles.carouselWrapper}
          onTouchStart={handleTouchStart}
          onTouchMove={handleTouchMove}
          onTouchEnd={handleTouchEnd}
        >
          <button className={`${styles.navButton} ${styles.navLeft}`} onClick={handlePrev} aria-label="Previous">
            <span aria-hidden>‹</span>
          </button>

          <div className={styles.carousel}>
            {renderCards()}
          </div>

          <button className={`${styles.navButton} ${styles.navRight}`} onClick={handleNext} aria-label="Next">
            <span aria-hidden>›</span>
          </button>
        </div>

        <div className={styles.details}>
          <div className={styles.detailsInner}>
            <h3 className={styles.detailsTitle}>{active.title}</h3>
            <p className={styles.detailsDesc}>{active.description}</p>
            <button
              className={styles.detailsCta}
              onClick={() => navigate(`/collections`)}
            >
              Explore Collection →
            </button>
          </div>
        </div>

        <div className={styles.indicators}>
          {OCCASIONS.map((_, idx) => (
            <button
              key={idx}
              className={`${styles.dot} ${idx === activeIndex ? styles.dotActive : ''}`}
              onClick={() => goTo(idx)}
              aria-label={`Go to slide ${idx + 1}`}
            />
          ))}
        </div>
      </div>
    </section>
  );
};

export default ForEveryYou;
